/**
 * Import Building Permits Data to Supabase
 *
 * Imports building permits data from CSVs generated by download-building-permits.ts
 *
 * Usage:
 *   # Import all geographies
 *   npx tsx scripts/import-building-permits.ts
 *
 *   # Import specific geography (supports multiple)
 *   npx tsx scripts/import-building-permits.ts --geo=county
 *   npx tsx scripts/import-building-permits.ts --geo=county --geo=state
 */

import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { createImportClient } from './census-economic-import/db-client';
import { parse } from 'csv-parse/sync';
import { createIngestionLogger } from './utils/ingestion-logger';

const DATA_DIR = join(process.cwd(), 'data/permits');

interface PermitRecord {
  period_date: string;
  fips_code: string;
  county_name: string;
  state_fips: string;
  region_code: string;
  division_code: string;
  sf_buildings: number | null;
  sf_units: number | null;
  sf_value: number | null;
  duplex_buildings: number | null;
  duplex_units: number | null;
  duplex_value: number | null;
  small_multi_buildings: number | null;
  small_multi_units: number | null;
  small_multi_value: number | null;
  large_multi_buildings: number | null;
  large_multi_units: number | null;
  large_multi_value: number | null;
  total_buildings: number | null;
  total_units: number | null;
  total_value: number | null;
  sf_units_yoy: number | null;
  total_units_yoy: number | null;
}

interface ImportResult {
  datasetId: string;
  success: boolean;
  recordsInserted: number;
  recordsUpdated: number;
  errors: number;
}

function parseNumeric(value: string | undefined): number | null {
  if (!value || value.trim() === '') return null;
  const num = parseFloat(value);
  return isNaN(num) ? null : num;
}

function parseInteger(value: string | undefined): number | null {
  if (!value || value.trim() === '') return null;
  const num = parseInt(value, 10);
  return isNaN(num) ? null : num;
}

function parsePermitsCSV(csvContent: string): PermitRecord[] {
  const records = parse(csvContent, {
    columns: true,
    skip_empty_lines: true,
    trim: true
  });

  // Deduplicate by period_date + fips_code (keep last occurrence)
  const seen = new Map<string, any>();
  for (const row of records) {
    const key = `${row.period_date}|${row.fips_code}`;
    seen.set(key, row);
  }

  return Array.from(seen.values()).map((row: any) => ({
    period_date: row.period_date,
    fips_code: row.fips_code,
    county_name: row.county_name || null,
    state_fips: row.state_fips,
    region_code: row.region_code || null,
    division_code: row.division_code || null,
    sf_buildings: parseInteger(row.sf_buildings),
    sf_units: parseInteger(row.sf_units),
    sf_value: parseInteger(row.sf_value),
    duplex_buildings: parseInteger(row.duplex_buildings),
    duplex_units: parseInteger(row.duplex_units),
    duplex_value: parseInteger(row.duplex_value),
    small_multi_buildings: parseInteger(row.small_multi_buildings),
    small_multi_units: parseInteger(row.small_multi_units),
    small_multi_value: parseInteger(row.small_multi_value),
    large_multi_buildings: parseInteger(row.large_multi_buildings),
    large_multi_units: parseInteger(row.large_multi_units),
    large_multi_value: parseInteger(row.large_multi_value),
    total_buildings: parseInteger(row.total_buildings),
    total_units: parseInteger(row.total_units),
    total_value: parseInteger(row.total_value),
    sf_units_yoy: parseNumeric(row.sf_units_yoy),
    total_units_yoy: parseNumeric(row.total_units_yoy)
  }));
}

async function importCountyPermits(supabase: any, records: PermitRecord[]): Promise<ImportResult> {
  const tableName = 'permits_county';
  let inserted = 0;
  let updated = 0;
  let errors = 0;

  // Process in batches of 500
  const batchSize = 500;
  const batches = [];
  for (let i = 0; i < records.length; i += batchSize) {
    batches.push(records.slice(i, i + batchSize));
  }

  console.log(`  Processing ${batches.length} batches of ${batchSize} records...`);

  for (let i = 0; i < batches.length; i++) {
    const batch = batches[i];

    const { data, error } = await supabase
      .from(tableName)
      .upsert(
        batch.map(r => ({
          period_date: r.period_date,
          fips_code: r.fips_code,
          county_name: r.county_name,
          state_fips: r.state_fips,
          region_code: r.region_code,
          division_code: r.division_code,
          sf_buildings: r.sf_buildings,
          sf_units: r.sf_units,
          sf_value: r.sf_value,
          duplex_buildings: r.duplex_buildings,
          duplex_units: r.duplex_units,
          duplex_value: r.duplex_value,
          small_multi_buildings: r.small_multi_buildings,
          small_multi_units: r.small_multi_units,
          small_multi_value: r.small_multi_value,
          large_multi_buildings: r.large_multi_buildings,
          large_multi_units: r.large_multi_units,
          large_multi_value: r.large_multi_value,
          total_buildings: r.total_buildings,
          total_units: r.total_units,
          total_value: r.total_value,
          sf_units_yoy: r.sf_units_yoy,
          total_units_yoy: r.total_units_yoy,
          updated_at: new Date().toISOString()
        })),
        { onConflict: 'period_date,fips_code' }
      );

    if (error) {
      console.error(`  Batch ${i + 1} error: ${error.message}`);
      errors += batch.length;
    } else {
      inserted += batch.length;
    }

    // Progress indicator
    if ((i + 1) % 10 === 0 || i === batches.length - 1) {
      process.stdout.write(`\r  Progress: ${i + 1}/${batches.length} batches`);
    }
  }

  console.log(''); // New line after progress

  return {
    datasetId: 'permits_county',
    success: errors === 0,
    recordsInserted: inserted,
    recordsUpdated: updated,
    errors
  };
}

