interface DatasetConfig {
  id: string;
  name: string;
  file: string;
  importer: (supabase: any, records: PermitRecord[]) => Promise<ImportResult>;
}

const DATASETS: DatasetConfig[] = [
  {
    id: 'county',
    name: 'Permits County',
    file: 'permits_county.csv',
    importer: importCountyPermits
  },
  {
    id: 'state',
    name: 'Permits State',
    file: 'permits_state.csv',
    importer: importStatePermits
  }
];

async function main() {
  const startTime = Date.now();
  const args = process.argv.slice(2);

  // Parse --geo arguments (supports multiple: --geo=county --geo=state)
  const geoFilters: string[] = [];
  for (const arg of args) {
    if (arg.startsWith('--geo=')) {
      geoFilters.push(arg.split('=')[1].toLowerCase());
    }
  }

  console.log('Building Permits Data Import');
  console.log('='.repeat(60));
  console.log(`Date: ${new Date().toISOString()}`);
  console.log(`Data directory: ${DATA_DIR}`);
  if (geoFilters.length > 0) {
    console.log(`Geography filter: ${geoFilters.join(', ')}`);
  }

  // Check if data directory exists
  if (!existsSync(DATA_DIR)) {
    console.error(`\nData directory not found: ${DATA_DIR}`);
    console.error('Please run download-building-permits.ts first to download the data.');
    process.exit(1);
  }

  // Create database client
  const supabase = createImportClient();

  const results: ImportResult[] = [];

  // Import each dataset
  for (const config of DATASETS) {
    // Skip if geography filter doesn't match
    if (geoFilters.length > 0 && !geoFilters.includes(config.id)) {
      continue;
    }

    const filePath = join(DATA_DIR, config.file);

    if (!existsSync(filePath)) {
      console.log(`\nSkipping ${config.name}: ${config.file} not found`);
      continue;
    }

    console.log(`\nImporting ${config.name}...`);
    console.log(`  Source: ${filePath}`);

    // Create ingestion logger for this dataset
    const logger = createIngestionLogger(supabase, {
      source: 'permits',
      tableName: `permits_${config.id}`,
      datasetId: `permits-${config.id}`
    });

    try {
      const csvContent = readFileSync(filePath, 'utf-8');
      const records = parsePermitsCSV(csvContent);

      console.log(`  Parsed ${records.length} records`);

      if (records.length === 0) {
        console.log(`  No records to import`);
        continue;
      }

      // Show date range
      const dates = records.map(r => r.period_date).sort();
      console.log(`  Date range: ${dates[0]} to ${dates[dates.length - 1]}`);

      // Start ingestion log
      await logger.start(records.length);

      const result = await config.importer(supabase, records);
      results.push(result);

      // Complete ingestion log
      await logger.complete({
        recordsProcessed: records.length,
        recordsSuccess: result.recordsInserted,
        recordsError: result.errors,
        errors: result.errors > 0 ? [`${result.errors} records failed`] : []
      });

      console.log(`  Imported: ${result.recordsInserted} records`);
      if (result.errors > 0) {
        console.log(`  Errors: ${result.errors}`);
      }
    } catch (error: any) {
      console.error(`  Error importing ${config.name}: ${error.message}`);
      await logger.fail(error.message);
      results.push({
        datasetId: config.id,
        success: false,
        recordsInserted: 0,
        recordsUpdated: 0,
        errors: 1
      });
    }
  }

  // Summary
  const duration = ((Date.now() - startTime) / 1000).toFixed(1);
  const totalRecords = results.reduce((sum, r) => sum + r.recordsInserted, 0);
  const totalErrors = results.reduce((sum, r) => sum + r.errors, 0);

  console.log(`\n${'='.repeat(60)}`);
  console.log('Import Summary');
  console.log('='.repeat(60));
  console.log(`Total records imported: ${totalRecords}`);
  console.log(`Total errors: ${totalErrors}`);
  console.log(`Duration: ${duration}s`);

  if (totalErrors > 0) {
    console.log('\nCompleted with errors');
    process.exit(1);
  } else {
    console.log('\nImport completed successfully!');
  }
}

main().catch(error => {
  console.error('Error:', error);
  process.exit(1);
});
